import pandas as pd
import numpy as np

# Load all available experiments
dfs = {}
for name in ['experiment_10_csv', 'experiment_11_csv', 'experiment_1_csv', 'experiment_2_csv', 'experiment_7_csv', 'experiment_8_csv', 'experiment_9_csv']:
    try:
        df = pd.read_csv(eval(name))
        dfs[name.replace('_csv','')] = df
        print(f"=== {name.replace('_csv','')} ===")
        print(f"Columns: {list(df.columns)}")
        # Show which do_ columns vary
        for col in df.columns:
            if col.startswith('do_'):
                vals = df[col].unique()
                if len(vals) > 1:
                    print(f"  {col}: varies over {len(vals)} values (range {df[col].min():.1f}-{df[col].max():.1f})")
                else:
                    print(f"  {col}: fixed at {df[col].unique()[0]:.1f}")
        # Summary of outcome
        if 'WaterClarityScore' in df.columns:
            print(f"  WaterClarityScore: mean={df['WaterClarityScore'].mean():.2f}, std={df['WaterClarityScore'].std():.2f}")
        print()
    except Exception as e:
        print(f"Error loading {name}: {e}")

# Group by experiment and show mean clarity
print("\n=== MEAN CLARITY BY EXPERIMENT ===")
for exp, df in dfs.items():
    if 'WaterClarityScore' in df.columns:
        print(f"  {exp}: clarity={df['WaterClarityScore'].mean():.2f}")
        for col in df.columns:
            if col.startswith('do_'):
                print(f"    {col} = {df[col].mean():.1f}")
